void test_FR_002_01(void)
{
    sensors_snapshot_t empty_readings = {0};

    TEST_ASSERT_TRUE(display_init(0U));
    sensors_init(0U);

    /* Advance through stabilization and start the splash at time zero. */
    display_process(UINT32_MAX, &empty_readings);
    TEST_ASSERT_TRUE(display_is_splash());

    /* The first scheduled DHT acquisition is due at startup + 1000 ms. */
    dht22_decode_ExpectAnyArgsAndReturn(true);
    sensors_process(1000U);
    TEST_ASSERT_TRUE(sensors_snapshot()->climate_valid);
    TEST_ASSERT_TRUE(display_is_splash());

    /* The splash remains active up to, but not including, its configured deadline. */
    display_process(LOGO_DISPLAY_MS - 1U, sensors_snapshot());
    TEST_ASSERT_TRUE(display_is_splash());

    /* At the configured deadline the display transitions out of the splash. */
    display_process(LOGO_DISPLAY_MS, sensors_snapshot());
    TEST_ASSERT_FALSE(display_is_splash());
}
